using System;using System.Linq;using System.Collections.Generic;using IdleIntelligence.Core;
namespace IdleIntelligence.Runtime {
 public static class ItemDetailsUI {
  public static string Text(GameState s,ItemInstance item){string lang=s.Settings.language;string T(string key)=>SettingsRules.Text(lang,key);string N(ScientificNumber n)=>NumberFormatting.Format(n,s.Settings.numberFormat);var d=Workshop.Definition(item);var lines=new List<string>{T("item:"+item.type)+" · "+T("rarity:"+ItemBalance.Rarities[item.rarity]),"Level "+item.level+" · "+T("game:forge")+" "+item.forge};var special=ItemDetailRules.Special(s,item);if(special!=null){lines.Add(special.Effect=="relay"?"Every "+special.TriggerInterval+" paid manual tap: "+special.BonusSeconds.ToString("F2")+" bonus seconds of regular passive Credits":"INT weighting contribution +"+(special.INTWeight*100).ToString("F2")+"% · future income only");lines.Add(special.Active?"Active":"Currently inactive; potential value");}foreach(string effect in d.Profiles[item.rarity].Distinct().Where(e=>e!="relay"&&e!="int-yield"))lines.Add(T("effect:"+effect)+": +"+(Workshop.Effect(s,item,effect)*100).ToString("F2")+" %");if(d.Role!="")lines.Add(T("effect:"+d.Role)+" · Cap "+(d.Cap*100).ToString("F2")+" % · "+"Current contribution"+": "+((Workshop.Equipped(s).Any(i=>i.id==item.id)?Workshop.DeviceInstance(s,item,d.Role):0)*100).ToString("F2")+" %");var p=ItemDetailRules.Upgrade(s,item.id);if(p!=null){lines.Add("When equipped · next level · "+p.Slot);lines.Add("Credits/s: "+N(Game.Income(p.Before))+" → "+N(Game.Income(p.After)));lines.Add("Data/s: "+N(Game.DataRate(p.Before))+" → "+N(Game.DataRate(p.After)));lines.Add("Compute: "+N(Game.Compute(p.Before))+" → "+N(Game.Compute(p.After)));foreach(string track in new[]{"quality","efficiency"})lines.Add((track=="integration"?"Integration":T("workshop:"+track))+" · Credits: "+N(Game.TrainingCost(p.Before,track))+" → "+N(Game.TrainingCost(p.After,track)));var a=ItemDetailRules.Special(p.Before,p.Before.Workshop.inventory.First(i=>i.id==item.id));var b=ItemDetailRules.Special(p.After,p.After.Workshop.inventory.First(i=>i.id==item.id));if(a!=null)lines.Add((a.Effect=="relay"?a.BonusSeconds:a.INTWeight*100).ToString("F2")+" → "+(b.Effect=="relay"?b.BonusSeconds:b.INTWeight*100).ToString("F2")+(a.Effect=="relay"?" bonus seconds":" %"));}return string.Join("\n",lines);}
 }
}
